cd /tmp && cat > gen_nd.mjs <<'EOF'
// Find maximal runs of consecutive \p{Nd} codepoints; Unicode guarantees decimal
// digits are encoded in contiguous aligned groups of ten with ascending values.
const re = /\p{Nd}/u;
const runs = [];
let start = -1;
for (let cp = 0; cp <= 0x10ffff; cp++) {
  const isNd = cp >= 0xd800 && cp <= 0xdfff ? false : re.test(String.fromCodePoint(cp));
  if (isNd) { if (start < 0) start = cp; }
  else if (start >= 0) { runs.push([start, cp - start]); start = -1; }
}
if (start >= 0) runs.push([start, 0x110000 - start]);
const bad = runs.filter(r => r[1] % 10 !== 0);
console.log('runs:', runs.length, 'non-multiple-of-10 runs:', JSON.stringify(bad));
const starts = [];
for (const [s, len] of runs) for (let k = 0; k < len / 10; k++) starts.push(s + 10 * k);
console.log('blocks:', starts.length);
console.log(JSON.stringify(starts));
EOF
node gen_nd.mjs

