/**
 * Python-shaped exceptions and traceback rendering.
 *
 * The reference program is a frozen (PyInstaller) CPython build.  When an
 * exception escapes module level it prints a traceback whose frames carry no
 * source text, followed by a PyInstaller trailer, and exits with status 1.
 * These classes carry enough information to reproduce that shape.
 */

/** Base class for every exception that models a Python one. */
export class PyException extends Error {
  constructor(pyType, pyMessage) {
    super(pyType + ': ' + pyMessage);
    this.name = pyType;
    this.pyType = pyType;
    this.pyMessage = pyMessage;
    /** Call stack, outermost first — the order Python prints it in. */
    this.frames = [];
  }
}

export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyUnicodeEncodeError extends PyException {
  constructor(message) {
    super('UnicodeEncodeError', message);
  }
}

/**
 * A traceback frame.  `line` values are the line numbers observed in the
 * reference build's tracebacks, so ported code reports the same positions.
 */
export function pyFrame(file, line, fn) {
  return { file, line, fn };
}

/** Run `thunk`, recording `frame` as its caller if a Python exception escapes. */
export function inFrame(frame, thunk) {
  try {
    return thunk();
  } catch (err) {
    if (err instanceof PyException) err.frames.unshift(frame);
    throw err;
  }
}

/** Render `err` the way CPython renders an uncaught exception. */
export function formatTraceback(err) {
  const lines = ['Traceback (most recent call last):'];
  for (const f of err.frames) {
    lines.push(`  File "${f.file}", line ${f.line}, in ${f.fn}`);
  }
  lines.push(`${err.pyType}: ${err.pyMessage}`);
  return lines.join('\n') + '\n';
}

/**
 * The PyInstaller trailer that follows the traceback.  The bracketed number is
 * the process id, which differs on every run of the reference binary too.
 */
export function formatFrozenTrailer(scriptName, pid) {
  return `[PYI-${pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`;
}

