/**
 * The two Unicode tables Python's own parsing rules depend on:
 *
 *  - the set of code points for which `str.isspace()` is true, used by
 *    `str.rstrip()` (which `base58.b58decode` applies to its input) and by the
 *    whitespace skipping in `int(str)`;
 *  - the decimal-digit (general category Nd) values accepted by `int(str)`.
 */

/**
 * Inclusive ranges where `str.isspace()` is true.  Note the C0 separators
 * 0x1c-0x1f, and that U+180E is *not* whitespace in current Unicode versions.
 */
const SPACE_RANGES = [
  [0x0009, 0x000d],
  [0x001c, 0x001f],
  [0x0020, 0x0020],
  [0x0085, 0x0085],
  [0x00a0, 0x00a0],
  [0x1680, 0x1680],
  [0x2000, 0x200a],
  [0x2028, 0x2029],
  [0x202f, 0x202f],
  [0x205f, 0x205f],
  [0x3000, 0x3000],
];

/** True when Python's `str.isspace()` would be true for this code point. */
export function isPySpace(cp) {
  if (cp === 0x20) return true;
  for (const [lo, hi] of SPACE_RANGES) {
    if (cp < lo) return false;
    if (cp <= hi) return true;
  }
  return false;
}

/** The whitespace bytes stripped by `bytes.rstrip()`: b' \t\n\r\x0b\f'. */
const BYTES_SPACE = [0x20, 0x09, 0x0a, 0x0d, 0x0b, 0x0c];

/** True when `bytes.rstrip()` would strip this byte. */
export function isBytesSpace(byte) {
  return BYTES_SPACE.includes(byte);
}

/**
 * First code point of every Unicode decimal-digit block.  Decimal digits are
 * always encoded in contiguous, aligned groups of ten in ascending value order,
 * so a code point's value is its offset from its block start.
 */
const DIGIT_BLOCK_STARTS = [
  48, 1632, 1776, 1984, 2406, 2534, 2662, 2790, 2918, 3046, 3174, 3302, 3430,
  3558, 3664, 3792, 3872, 4160, 4240, 6112, 6160, 6470, 6608, 6784, 6800, 6992,
  7088, 7232, 7248, 42528, 43216, 43264, 43472, 43504, 43600, 44016, 65296,
  66720, 68912, 69734, 69872, 69942, 70096, 70384, 70736, 70864, 71248, 71360,
  71472, 71904, 72016, 72784, 73040, 73120, 73552, 92768, 92864, 93008, 120782,
  120792, 120802, 120812, 120822, 123200, 123632, 124144, 125264, 130032,
];

/**
 * Value 0-9 of a Unicode decimal digit, or -1 if the code point is not one.
 * `int('٥')` is 5 in Python, so a faithful port cannot special-case ASCII only.
 */
export function pyDigitValue(cp) {
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30; // fast path for ASCII
  let lo = 0;
  let hi = DIGIT_BLOCK_STARTS.length - 1;
  let start = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (DIGIT_BLOCK_STARTS[mid] <= cp) {
      start = DIGIT_BLOCK_STARTS[mid];
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (start < 0) return -1;
  const value = cp - start;
  return value < 10 ? value : -1;
}

