/**
 * Python `bytes` modelled as a plain JS array of integers in 0-255, together
 * with the codecs that produce them and the `repr()` that prints them.
 *
 * Byte sequences are deliberately plain arrays: no typed-array or binary-buffer
 * abstraction is used anywhere in this port.
 */

import { PyUnicodeEncodeError } from './errors.mjs';
import { escapeCodePoint } from './pystr.mjs';
import { isBytesSpace } from './unicode.mjs';

/**
 * Build the message CPython raises when a codec cannot encode part of a string.
 * A maximal run of unencodable characters is reported as one error, and the
 * noun is pluralised when the run is longer than one character.
 */
function encodeErrorMessage(codec, cps, start, end, reason) {
  if (end - start === 1) {
    return `'${codec}' codec can't encode character ${"'" + escapeCodePoint(cps[start]) + "'"} in position ${start}: ${reason}`;
  }
  return `'${codec}' codec can't encode characters in position ${start}-${end - 1}: ${reason}`;
}

/** Python's `str.encode('ascii')`. */
export function asciiEncode(str) {
  const cps = [];
  for (const ch of str) cps.push(ch.codePointAt(0));
  for (let i = 0; i < cps.length; i += 1) {
    if (cps[i] > 0x7f) {
      let end = i + 1;
      while (end < cps.length && cps[end] > 0x7f) end += 1;
      throw new PyUnicodeEncodeError(
        encodeErrorMessage('ascii', cps, i, end, 'ordinal not in range(128)'),
      );
    }
  }
  return cps;
}

/** Python's `str.encode()` — i.e. UTF-8, which rejects surrogates. */
export function utf8Encode(str) {
  const cps = [];
  for (const ch of str) cps.push(ch.codePointAt(0));
  const out = [];
  for (let i = 0; i < cps.length; i += 1) {
    const cp = cps[i];
    if (cp >= 0xd800 && cp <= 0xdfff) {
      let end = i + 1;
      while (end < cps.length && cps[end] >= 0xd800 && cps[end] <= 0xdfff) end += 1;
      throw new PyUnicodeEncodeError(
        encodeErrorMessage('utf-8', cps, i, end, 'surrogates not allowed'),
      );
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

/** Python's `bytes.decode('ascii')`, for turning byte values back into chars. */
export function asciiDecode(bytes) {
  let out = '';
  for (const b of bytes) out += String.fromCharCode(b);
  return out;
}

/** `bytes.lstrip(<single byte>)`. */
export function lstripByte(bytes, byte) {
  let start = 0;
  while (start < bytes.length && bytes[start] === byte) start += 1;
  return bytes.slice(start);
}

/** `bytes.rstrip()` — trailing b' \t\n\r\x0b\f'. */
export function rstripBytes(bytes) {
  let end = bytes.length;
  while (end > 0 && isBytesSpace(bytes[end - 1])) end -= 1;
  return bytes.slice(0, end);
}

/**
 * Python's `repr()` of a bytes object, which is what `print(b'...')` writes.
 *
 * The literal is single quoted unless the value contains a single quote and no
 * double quote.  Only `\\`, `\t`, `\n`, `\r` and the delimiter get short
 * escapes; every other non-printable byte becomes lowercase `\xNN`.
 */
export function bytesRepr(bytes) {
  let hasSingle = false;
  let hasDouble = false;
  for (const b of bytes) {
    if (b === 0x27) hasSingle = true;
    else if (b === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  let body = '';
  for (const b of bytes) {
    if (b === quote || b === 0x5c) body += '\\' + String.fromCharCode(b);
    else if (b === 0x09) body += '\\t';
    else if (b === 0x0a) body += '\\n';
    else if (b === 0x0d) body += '\\r';
    else if (b >= 0x20 && b < 0x7f) body += String.fromCharCode(b);
    else body += '\\x' + b.toString(16).padStart(2, '0');
  }
  const q = String.fromCharCode(quote);
  return 'b' + q + body + q;
}

