/**
 * The base58 digit alphabet.
 *
 * Derived by observation: encoding the integers 0 through 57 one at a time and
 * reading back the single digit produced for each yields exactly this order,
 * and confirms that `0`, `O`, `I` and `l` are absent.
 */

export const BITCOIN_ALPHABET_TEXT =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

/** The alphabet as byte values, mirroring the `bytes` constant in the original. */
export const BITCOIN_ALPHABET = (() => {
  const bytes = [];
  for (let i = 0; i < BITCOIN_ALPHABET_TEXT.length; i += 1) {
    bytes.push(BITCOIN_ALPHABET_TEXT.charCodeAt(i));
  }
  return bytes;
})();

const INDEX_CACHE = new WeakMap();

/**
 * Position of `byte` in `alphabet`, or -1 — i.e. `alphabet.index(char)` without
 * the linear scan.  Mirrors that lookup failing for unknown digits.
 */
export function digitIndex(alphabet, byte) {
  let table = INDEX_CACHE.get(alphabet);
  if (table === undefined) {
    table = new Map();
    for (let i = 0; i < alphabet.length; i += 1) table.set(alphabet[i], i);
    INDEX_CACHE.set(alphabet, table);
  }
  const index = table.get(byte);
  return index === undefined ? -1 : index;
}

