import { inFrame } from '../errors.mjs';
import { asciiEncode } from '../pybytes.mjs';
import { FRAME_SCRUB_INPUT } from './frames.mjs';

/** True for the plain integer arrays this port uses to model `bytes`. */
export function isByteArray(value) {
