 * Coerce `v` to a byte array.  Encoding a non-ASCII string raises the same
 * UnicodeEncodeError the original does, attributed to `scrub_input`.
 */
export function scrubInput(v) {
  if (typeof v === 'string') {
    return inFrame(FRAME_SCRUB_INPUT, () => asciiEncode(v));
  }
