 * The integer face of base58: `b58encode_int` and `b58decode_int`.
 */

import { PyValueError, inFrame } from '../errors.mjs';
import { pyDivmod } from '../pyint.mjs';
import { rstripBytes } from '../pybytes.mjs';
import { reprChar, rstripPyStr } from '../pystr.mjs';
import { BITCOIN_ALPHABET, digitIndex } from './alphabet.mjs';
import { FRAME_B58DECODE_INT } from './frames.mjs';
import { scrubInput } from './scrub.mjs';

/**
 * Encode a non-negative integer as base58 digits, returning a byte array.
 *
 * `defaultOne` reproduces the original's `default_one` flag: zero encodes as a
 * single leading digit when set, and as nothing when clear (which is how
 * `b58encode` represents an empty payload).
 *
 * The loop is the original's `while i:` over floor `divmod`.  That means a
 * negative input never terminates — as in the reference program, where a
 * negative `--f` or `--g` hangs rather than raising.
 */
export function b58encodeInt(i, options = {}) {
  const alphabet = options.alphabet || BITCOIN_ALPHABET;
  const defaultOne = options.defaultOne !== false;
  const base = BigInt(alphabet.length);

  if (i === 0n && defaultOne) return [alphabet[0]];

  const digits = [];
  let n = i;
  while (n !== 0n) {
    const [quotient, remainder] = pyDivmod(n, base);
    n = quotient;
    digits.push(alphabet[Number(remainder)]);
  }
  digits.reverse();
  return digits;
}

/**
 * Decode base58 digits to an integer.  Accepts a string or a byte array; a
 * trailing run of whitespace is dropped first, because the alphabet contains no
 * space and so cannot mean anything by it.
 */
export function b58decodeInt(v, options = {}) {
  const alphabet = options.alphabet || BITCOIN_ALPHABET;
  let value = v;
  if (!alphabet.includes(0x20)) {
    value = typeof value === 'string' ? rstripPyStr(value) : rstripBytes(value);
  }
  const bytes = scrubInput(value);
  const base = BigInt(alphabet.length);

  return inFrame(FRAME_B58DECODE_INT, () => {
    let decimal = 0n;
    for (const byte of bytes) {
      const index = digitIndex(alphabet, byte);
      if (index < 0) {
        throw new PyValueError(`Invalid character ${reprChar(byte)}`);
      }
      decimal = decimal * base + BigInt(index);
    }
    return decimal;
  });
}

