/**
 * The byte-string face of base58: `b58encode` and `b58decode`.
 *
 * Both treat the payload as one big-endian integer, and both carry leading zero
 * bytes separately from that integer — a zero byte is invisible to the integer
 * but must survive the round trip, so each one is spelled as a leading first
 * digit of the alphabet.
 */

import { inFrame } from '../errors.mjs';
import { intFromBytesBE, pyDivmod } from '../pyint.mjs';
import { lstripByte, rstripBytes } from '../pybytes.mjs';
import { rstripPyStr } from '../pystr.mjs';
import { BITCOIN_ALPHABET } from './alphabet.mjs';
import { FRAME_B58DECODE_CALL_INT, FRAME_B58DECODE_SCRUB } from './frames.mjs';
import { b58decodeInt, b58encodeInt } from './int.mjs';
import { scrubInput } from './scrub.mjs';

/** Encode a byte array as base58, returning the digits as a byte array. */
export function b58encode(v, options = {}) {
  const alphabet = options.alphabet || BITCOIN_ALPHABET;
  const bytes = scrubInput(v);

  const originalLength = bytes.length;
  const stripped = lstripByte(bytes, 0x00);
  const strippedLength = stripped.length;

  const accumulator = intFromBytesBE(stripped);
  const digits = b58encodeInt(accumulator, { defaultOne: false, alphabet });

  const prefix = [];
  for (let i = 0; i < originalLength - strippedLength; i += 1) prefix.push(alphabet[0]);
  return prefix.concat(digits);
}

/** Decode base58 digits (string or byte array) back to a byte array. */
export function b58decode(v, options = {}) {
  const alphabet = options.alphabet || BITCOIN_ALPHABET;

  // Trailing whitespace is dropped while the input is still text, so Unicode
  // whitespace is tolerated here even though only ASCII survives the encode.
  const trimmed = typeof v === 'string' ? rstripPyStr(v) : rstripBytes(v);
  const bytes = inFrame(FRAME_B58DECODE_SCRUB, () => scrubInput(trimmed));

  const originalLength = bytes.length;
  const stripped = lstripByte(bytes, alphabet[0]);
  const strippedLength = stripped.length;

  let accumulator = inFrame(FRAME_B58DECODE_CALL_INT, () =>
    b58decodeInt(stripped, { alphabet }),
  );

  const result = [];
  while (accumulator > 0n) {
    const [quotient, remainder] = pyDivmod(accumulator, 256n);
    accumulator = quotient;
    result.push(Number(remainder));
  }
  for (let i = 0; i < originalLength - strippedLength; i += 1) result.push(0x00);
  result.reverse();
  return result;
}

