/**
 * The checksummed forms: `b58encode_check` and `b58decode_check`.
 *
 * A four-byte checksum — the first four bytes of the doubled SHA-256 of the
 * payload — is appended to the payload before base58 encoding, and verified
 * after decoding.
 */

import { PyValueError } from '../errors.mjs';
import { sha256d } from '../sha256.mjs';
import { BITCOIN_ALPHABET } from './alphabet.mjs';
import { b58decode, b58encode } from './core.mjs';
import { scrubInput } from './scrub.mjs';

const CHECKSUM_LENGTH = 4;

function checksum(payload) {
  return sha256d(payload).slice(0, CHECKSUM_LENGTH);
}

/** Encode a byte array with its checksum appended. */
export function b58encodeCheck(v, options = {}) {
  const alphabet = options.alphabet || BITCOIN_ALPHABET;
  const payload = scrubInput(v);
  return b58encode(payload.concat(checksum(payload)), { alphabet });
}

/** Decode a checksummed value, returning the payload without its checksum. */
export function b58decodeCheck(v, options = {}) {
  const alphabet = options.alphabet || BITCOIN_ALPHABET;
  const decoded = b58decode(v, { alphabet });

  const payload = decoded.slice(0, decoded.length - CHECKSUM_LENGTH);
  const check = decoded.slice(decoded.length - CHECKSUM_LENGTH);
  const expected = checksum(payload);

  const matches =
    check.length === expected.length && check.every((byte, i) => byte === expected[i]);
  if (!matches) throw new PyValueError('Invalid checksum');

  return payload;
}

