/**
 * Python `str` operations that the reference program's behaviour depends on,
 * plus the `repr()` spellings that appear inside its error messages.
 */

import { isPySpace } from './unicode.mjs';

/** Code points of a JS string, so indices count characters the way Python does. */
export function codePoints(str) {
  const out = [];
  for (const ch of str) out.push(ch.codePointAt(0));
  return out;
}

/** Python's `str.rstrip()` — trailing Unicode whitespace only. */
export function rstripPyStr(str) {
  let end = str.length;
  while (end > 0) {
    const cp = str.codePointAt(end - 1);
    // A trailing low surrogate is never whitespace, so code-unit stepping is safe.
    if (!isPySpace(cp)) break;
    end -= 1;
  }
  return str.slice(0, end);
}

/** Python's `str.strip()` — leading and trailing Unicode whitespace. */
export function stripPyStr(str) {
  let start = 0;
  let end = str.length;
  while (start < end && isPySpace(str.codePointAt(start))) start += 1;
  while (end > start && isPySpace(str.codePointAt(end - 1))) end -= 1;
  return str.slice(start, end);
}

/**
 * The `\x`/`\u`/`\U` escape CPython uses for a code point inside a codec error
 * message, where non-ASCII is always escaped regardless of printability.
 */
export function escapeCodePoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * Python's `repr()` of a one-character string, as interpolated by
 * `"Invalid character {!r}"`.  A lone `'` flips the literal to double quotes.
 */
export function reprChar(cp) {
  const quote = cp === 0x27 ? '"' : "'";
  let body;
  if (cp === 0x5c) body = '\\\\';
  else if (cp === 0x09) body = '\\t';
  else if (cp === 0x0a) body = '\\n';
  else if (cp === 0x0d) body = '\\r';
  else if (cp >= 0x20 && cp < 0x7f) body = String.fromCodePoint(cp);
  else body = escapeCodePoint(cp);
  return quote + body + quote;
}

