/**
 * A clone of the slice of Python's `argparse` this program relies on: long
 * options that each take exactly one value, an automatic `-h/--help`, required
 * argument checking, and `int` conversion.
 *
 * Behaviours reproduced deliberately, all confirmed against the reference:
 *  - `--a v` and `--a=v` are equivalent, and a later occurrence overwrites an
 *    earlier one;
 *  - unique prefixes of a long option are accepted (`--h` means `--help`);
 *  - a bare `-`, a negative number, and any token containing a space count as
 *    values even though they start with a dash;
 *  - `--` makes everything after it a non-option token, and is itself reported;
 *  - errors are prefixed by the usage line, sent to stderr, and exit with 2;
 *  - the checks fire in this order: value conversion, then missing required
 *    arguments, then unrecognised tokens.
 */

import { pyIntFromStr } from './pyint.mjs';
import { reprStr } from './pystr.mjs';

/** Python's `SystemExit`, raised by `--help` and by argument errors. */
export class SystemExit extends Error {
  constructor(code) {
    super('SystemExit: ' + code);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const INDENT = 2;
const MAX_HELP_POSITION = 24;

export class ArgumentParser {
  constructor(options = {}) {
    this.prog = options.prog || 'prog';
    this.writeOut = options.writeOut || ((text) => process.stdout.write(text));
    this.writeErr = options.writeErr || ((text) => process.stderr.write(text));
    this.actions = [];
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      nargs: 0,
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, config = {}) {
    const names = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const longest = names.find((name) => name.startsWith('--')) || names[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
    const action = {
      optionStrings: names,
      dest,
      nargs: config.nargs === 0 ? 0 : 1,
      type: config.type || 'str',
      required: config.required === true,
      metavar: config.metavar || dest.toUpperCase(),
      help: config.help,
    };
    this.actions.push(action);
    for (const name of names) this.optionStringActions.set(name, action);
    return action;
  }

  /** `[-h]` for the optional help, `--a A` for a required value option. */
  formatActionInvocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return `${action.optionStrings[0]} ${action.metavar}`;
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const invocation =
        action.nargs === 0
          ? action.optionStrings[0]
          : `${action.optionStrings[0]} ${action.metavar}`;
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => this.formatActionInvocation(action));
    const longest = invocations.reduce((max, text) => Math.max(max, text.length), 0);
    const helpPosition = Math.min(longest + INDENT + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;

    let text = this.formatUsage() + '\noptions:\n';
    this.actions.forEach((action, i) => {
      const invocation = invocations[i];
      if (!action.help) {
        text += ' '.repeat(INDENT) + invocation + '\n';
      } else if (invocation.length <= actionWidth) {
        text +=
          ' '.repeat(INDENT) + invocation.padEnd(actionWidth) + '  ' + action.help + '\n';
      } else {
        text +=
          ' '.repeat(INDENT) + invocation + '\n' + ' '.repeat(helpPosition) + action.help + '\n';
      }
    });
    return text;
  }

  printHelp() {
    this.writeOut(this.formatHelp());
  }

  error(message) {
    this.writeErr(this.formatUsage());
    this.writeErr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * argparse's `_parse_optional`.  Returns null when the token is a value, an
   * entry with a null action when it looks like an option nobody declared, and
   * otherwise the matched action.
   */
  parseOptional(argString) {
    if (argString.length === 0) return null;
    if (argString[0] !== '-') return null;

    const exact = this.optionStringActions.get(argString);
    if (exact) return { action: exact, optionString: argString, explicitArg: null };

    if (argString.length === 1) return null; // a bare '-' is a value

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      const action = this.optionStringActions.get(optionString);
      if (action) {
        return { action, optionString, explicitArg: argString.slice(equals + 1) };
      }
    }

    const matches = this.getOptionTuples(argString);
    if (matches.length > 1) {
      const names = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (matches.length === 1) return matches[0];

    // No option looks like a negative number here, so numbers stay values.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** argparse's `_get_option_tuples`: prefix matching over declared options. */
  getOptionTuples(argString) {
    const equals = argString.indexOf('=');
    const prefix = equals === -1 ? argString : argString.slice(0, equals);
    const explicitArg = equals === -1 ? null : argString.slice(equals + 1);

    const matches = [];
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString.startsWith(prefix)) matches.push({ action, optionString, explicitArg });
    }
    return matches;
  }

  /** True when argparse would classify the token as an option rather than a value. */
  looksLikeOption(argString) {
    return this.parseOptional(argString) !== null;
  }

  convertValue(action, optionString, text) {
    if (action.type !== 'int') return text;
    const value = pyIntFromStr(text);
    if (value === null) {
      this.error(`argument ${optionString}: invalid int value: ${reprStr(text)}`);
    }
    return value;
  }

  parseArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.nargs !== 0) namespace[action.dest] = undefined;
    }

    const extras = [];
    const seen = new Set();
    let valuesOnly = false;

    for (let i = 0; i < argv.length; ) {
      const token = argv[i];

      if (valuesOnly) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (token === '--') {
        valuesOnly = true;
        extras.push(token);
        i += 1;
        continue;
      }

      const parsed = this.parseOptional(token);
      if (parsed === null || parsed.action === null) {
        extras.push(token);
        i += 1;
        continue;
      }

      const { action, optionString, explicitArg } = parsed;
      i += 1;

      if (action.nargs === 0) {
        this.printHelp();
        throw new SystemExit(0);
      }

      let text;
      if (explicitArg !== null) {
        text = explicitArg;
      } else {
        const next = i < argv.length ? argv[i] : undefined;
        if (next === undefined || this.looksLikeOption(next)) {
          this.error(`argument ${optionString}: expected one argument`);
        }
        text = next;
        i += 1;
      }

      namespace[action.dest] = this.convertValue(action, optionString, text);
      seen.add(action);
    }

    const missing = this.actions.filter((action) => action.required && !seen.has(action));
    if (missing.length > 0) {
      const names = missing.map((action) => action.optionStrings.join('/')).join(', ');
      this.error(`the following arguments are required: ${names}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

