#!/usr/bin/env node
/**
 * Node.js port of dataset/base58/test20.py.
 *
 * The original combines every public base58 entry point in one pass and prints
 * twelve values: ten `bytes` objects, one plain integer, and one more `bytes`.
 * Each statement below sits at the same source line as the statement it ports,
 * so an escaping exception reports the coordinates the reference build reports.
 */

import { basename } from 'node:path';

import { ArgumentParser, SystemExit } from './lib/argparse.mjs';
import {
  PyException,
  formatFrozenTrailer,
  formatTraceback,
  inFrame,
  pyFrame,
} from './lib/errors.mjs';
import { bytesRepr, utf8Encode } from './lib/pybytes.mjs';
import {
  b58decode,
  b58decodeCheck,
  b58decodeInt,
  b58encode,
  b58encodeCheck,
  b58encodeInt,
} from './lib/base58/index.mjs';

/**
 * The module name the reference build names in its tracebacks.  Its frames are
 * reported against the original source, which is what the ported line numbers
 * below refer to.
 */
const SOURCE_FILE = 'test20.py';
const FROZEN_SCRIPT = 'test20';

function buildParser() {
  const parser = new ArgumentParser({
    prog: basename(process.argv[1] || 'test20.mjs'),
  });
  parser.addArgument('--a', { type: 'str', required: true });
  parser.addArgument('--b', { type: 'str', required: true });
  parser.addArgument('--c', { type: 'str', required: true });
  parser.addArgument('--d', { type: 'str', required: true });
  parser.addArgument('--e', { type: 'str', required: true });
  parser.addArgument('--f', { type: 'int', required: true });
  parser.addArgument('--g', { type: 'int', required: true });
  return parser;
}

function run() {
  const parser = buildParser();
  const args = parser.parseArgs(process.argv.slice(2));

  /** Evaluate `thunk` as if it were the module-level statement on `line`. */
  const atLine = (line, thunk) => inFrame(pyFrame(SOURCE_FILE, line, '<module>'), thunk);

  // Final composite scenario: several APIs called in combination.
  const enc1 = atLine(15, () => b58encode(utf8Encode(args.a))); // basic encode 1
  const dec1 = atLine(16, () => b58decode(args.b)); // basic decode 1
  const encCheck1 = atLine(17, () => b58encodeCheck(utf8Encode(args.c))); // checksummed encode 1
  const decCheck1 = atLine(18, () => b58decodeCheck(encCheck1)); // checksummed decode 1
  const encInt1 = atLine(19, () => b58encodeInt(args.f)); // integer encode 1
  const decInt1 = atLine(20, () => b58decodeInt(encInt1)); // integer decode 1
  const enc2 = atLine(21, () => b58encode(utf8Encode(args.d))); // basic encode 2
  const dec2 = atLine(22, () => b58decode(args.e)); // basic decode 2
  const encInt2 = atLine(23, () => b58encodeInt(args.g)); // integer encode 2
  const encCheck2 = atLine(24, () => b58encodeCheck(dec1)); // checksum the decoded result
  const decCheck2 = atLine(25, () => b58decodeCheck(encCheck2)); // checksummed decode 2
  const enc3 = atLine(26, () => b58encode(decCheck2)); // re-encode the checksummed result

  console.log(bytesRepr(enc1));
  console.log(bytesRepr(dec1));
  console.log(bytesRepr(encCheck1));
  console.log(bytesRepr(decCheck1));
  console.log(bytesRepr(encInt1));
  console.log(decInt1.toString());
  console.log(bytesRepr(enc2));
  console.log(bytesRepr(dec2));
  console.log(bytesRepr(encInt2));
  console.log(bytesRepr(encCheck2));
  console.log(bytesRepr(decCheck2));
  console.log(bytesRepr(enc3));
}

function main() {
  try {
    run();
  } catch (err) {
    if (err instanceof SystemExit) {
      // Leave the exit code for a natural exit so buffered output still flushes.
      process.exitCode = err.code;
      return;
    }
    if (err instanceof PyException) {
      process.stderr.write(formatTraceback(err));
      process.stderr.write(formatFrozenTrailer(FROZEN_SCRIPT, process.pid));
      process.exitCode = 1;
      return;
    }
    throw err;
  }
}

main();

