/**
 * Whitespace as `int(str)` sees it, which is *not* the same set as
 * `str.isspace()`.
 *
 * `int()` first rewrites its argument to ASCII: characters below 127 are copied
 * through untouched, while anything above that which is Unicode whitespace
 * becomes a plain space.  The resulting string is then scanned with the C
 * `isspace`, so the C0 separators 0x1c-0x1f — whitespace to `str.strip()` —
 * survive the rewrite and are rejected as digits, whereas U+00A0 or U+3000 are
 * accepted.
 */
const ASCII_INT_SPACE = [0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20];

export function isIntSpace(cp) {
  if (cp < 0x7f) return ASCII_INT_SPACE.includes(cp);
  return isPySpace(cp);
}

