/**
 * Python `str` operations that the reference program's behaviour depends on,
 * plus the `repr()` spellings that appear inside its error messages.
 */

import { isPySpace } from './unicode.mjs';

/** Code points of a JS string, so indices count characters the way Python does. */
export function codePoints(str) {
  const out = [];
  for (const ch of str) out.push(ch.codePointAt(0));
  return out;
}

/** Python's `str.rstrip()` — trailing Unicode whitespace only. */
export function rstripPyStr(str) {
  let end = str.length;
  while (end > 0) {
    const cp = str.codePointAt(end - 1);
    // A trailing low surrogate is never whitespace, so code-unit stepping is safe.
    if (!isPySpace(cp)) break;
    end -= 1;
  }
  return str.slice(0, end);
}

/** Python's `str.strip()` — leading and trailing Unicode whitespace. */
export function stripPyStr(str) {
  let start = 0;
  let end = str.length;
  while (start < end && isPySpace(str.codePointAt(start))) start += 1;
  while (end > start && isPySpace(str.codePointAt(end - 1))) end -= 1;
  return str.slice(start, end);
}

/**
 * The `\x`/`\u`/`\U` escape CPython uses for a code point inside a codec error
 * message, where non-ASCII is always escaped regardless of printability.
 */
export function escapeCodePoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * Python's `repr()` of a one-character string, as interpolated by
 * `"Invalid character {!r}"`.  A lone `'` flips the literal to double quotes.
 */
export function reprChar(cp) {
  const quote = cp === 0x27 ? '"' : "'";
  let body;
  if (cp === 0x5c) body = '\\\\';
  else if (cp === 0x09) body = '\\t';
  else if (cp === 0x0a) body = '\\n';
  else if (cp === 0x0d) body = '\\r';
  else if (cp >= 0x20 && cp < 0x7f) body = String.fromCodePoint(cp);
  else body = escapeCodePoint(cp);
  return quote + body + quote;
}

/**
 * Python's `str.isprintable()`: everything outside the control, format,
 * surrogate, private-use, unassigned and separator categories, plus the space.
 */
const NON_PRINTABLE = /[\p{C}\p{Z}]/u;

function isPrintable(cp) {
  if (cp === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

/**
 * Python's `repr()` of a string, as interpolated by argparse's `%r` in
 * `invalid int value: %r`.  Printable characters — including non-ASCII ones —
 * are kept verbatim; the rest are escaped.
 */
export function reprStr(str) {
  const cps = codePoints(str);
  const quote = cps.includes(0x27) && !cps.includes(0x22) ? '"' : "'";
  const quoteCp = quote.charCodeAt(0);
  let body = '';
  for (const cp of cps) {
    if (cp === quoteCp || cp === 0x5c) body += '\\' + String.fromCodePoint(cp);
    else if (cp === 0x09) body += '\\t';
    else if (cp === 0x0a) body += '\\n';
    else if (cp === 0x0d) body += '\\r';
    else if (isPrintable(cp)) body += String.fromCodePoint(cp);
    else body += escapeCodePoint(cp);
  }
  return quote + body + quote;
}

/**
 * Python integer semantics: arbitrary precision (BigInt), floor division, the
 * `int(str)` parser, and big-endian conversion to and from byte arrays.
 */

import { pyDigitValue } from './unicode.mjs';
import { stripPyStr } from './pystr.mjs';

/**
 * Python's `divmod`, which floors the quotient and gives the remainder the
 * divisor's sign.  BigInt division truncates instead, so the correction below
 * is what keeps ported loops behaving like the original ones.
 */
export function pyDivmod(a, b) {
  let q = a / b;
  let r = a % b;
  if (r !== 0n && r < 0n !== b < 0n) {
    q -= 1n;
    r += b;
  }
  return [q, r];
}

/** Python's `int.from_bytes(v, byteorder='big')`. */
export function intFromBytesBE(bytes) {
  let acc = 0n;
  for (const b of bytes) acc = (acc << 8n) | BigInt(b);
  return acc;
}

/**
 * Python's `int(str)`, returning a BigInt, or `null` when Python would raise
 * ValueError.  Accepts surrounding Unicode whitespace, an optional sign, any
 * Unicode decimal digits, and single underscores between digits.
 */
export function pyIntFromStr(str) {
  const trimmed = stripPyStr(str);
  const chars = [];
  for (const ch of trimmed) chars.push(ch.codePointAt(0));

  let i = 0;
  let negative = false;
  if (i < chars.length && (chars[i] === 0x2b || chars[i] === 0x2d)) {
    negative = chars[i] === 0x2d;
    i += 1;
  }
  if (i >= chars.length) return null;

  let value = 0n;
  let previousWasDigit = false;
  let digitCount = 0;
  for (; i < chars.length; i += 1) {
    if (chars[i] === 0x5f) {
      // An underscore is only legal between two digits.
      if (!previousWasDigit) return null;
      previousWasDigit = false;
      continue;
    }
    const digit = pyDigitValue(chars[i]);
    if (digit < 0) return null;
    value = value * 10n + BigInt(digit);
    previousWasDigit = true;
    digitCount += 1;
  }
  if (digitCount === 0 || !previousWasDigit) return null;
  return negative ? -value : value;
}

