import { runCase, report } from './harness.mjs';

const cases = [];
const wrap = (v) => ['--a', 'x', '--b', '2', '--c', 'x', '--d', 'y', '--e', '3', '--f', v, '--g', '1'];

// Every ASCII character as a surrounding "whitespace" candidate for int().
for (let cp = 1; cp < 128; cp += 1) {
  const ch = String.fromCharCode(cp);
  cases.push(wrap(ch + '42'));
  cases.push(wrap('42' + ch));
  cases.push(wrap(ch + '42' + ch));
}

// Non-ASCII whitespace (normalised to a space by int()) versus non-whitespace.
const nonAscii = [
  '', ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', '　', '​', '᠎', '﻿', '−', '­',
];
for (const ch of nonAscii) {
  cases.push(wrap(ch + '42'));
  cases.push(wrap('42' + ch));
  cases.push(wrap('4' + ch + '2'));
}

// Digit-like characters: only the decimal-digit category counts.
const digitish = [
  '٥', '۵', '৫', '५', '๕', '໕', '༥', '၅', '៥', '᠕', '᥅', '꘡', '５', '𝟓', '𝟝',
  '²', '½', 'Ⅷ', '〇', '㊄', '⑤', '⓹', '𐍁', 'Ⅴ',
];
for (const ch of digitish) {
  cases.push(wrap(ch));
  cases.push(wrap('1' + ch));
  cases.push(wrap('+' + ch));
  cases.push(wrap(ch + ch + ch));
  cases.push(wrap('1_' + ch));
}

// Sign, underscore and radix-prefix forms.
const forms = [
  '5', '+5', '-0', '007', '0', '00', '0_0', '1_000', '1_0_0_0', '1__0', '_5', '5_',
  '+_5', '-_5', '+', '-', '++5', '--5', '+-5', '', ' ', '0x10', '0o17', '0b101',
  '5.0', '.5', '5.', '5e3', '1e0', 'abc', '4 2', '+ 5', ' + 5', '5 5', 'inf', 'nan',
  '9'.repeat(80), '1'.repeat(200), ' +5', '+5 ', '0'.repeat(50) + '7',
];
for (const v of forms) cases.push(wrap(v));

// The same forms on --g, to prove both integer options share one code path.
for (const v of forms) {
  cases.push(['--a', 'x', '--b', '2', '--c', 'x', '--d', 'y', '--e', '3', '--f', '1', '--g', v]);
}

report(cases.map((c) => runCase(c)), { showStderr: false });

